pub fn grants_for_tier(name: &str) -> Option<&'static [&'static str]> {
    match name {
        "none" => Some(&TIER_NONE),
        "safe" => Some(&TIER_SAFE),
        "standard" => Some(&TIER_STANDARD),
        "full" => Some(&TIER_FULL),
        _ => None,
    }
}

pub fn minimum_tier_for(capability: &str) -> Option<&'static str> {
    if TIER_SAFE.contains(&capability) {
        return Some("safe");
    }
    if TIER_STANDARD.contains(&capability) {
        return Some("standard");
    }
    if TIER_FULL.contains(&capability) {
        return Some("full");
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn explicit_policy_tier_has_no_ambient_grants() {
        assert_eq!(grants_for_tier("none"), Some(&[][..]));
        assert!(grants_for_tier("unknown").is_none());
    }

    #[test]
    fn tiers_are_monotone() {
        for capability in TIER_NONE {
            assert!(TIER_SAFE.contains(&capability));
        }
        for capability in TIER_SAFE {
            assert!(TIER_STANDARD.contains(&capability));
        }
        for capability in TIER_STANDARD {
            assert!(TIER_FULL.contains(&capability));
        }
    }
}
